    pass

class CsvExporter(FileExporter):
    name = "csv"
    def export(self, rows):
        return "\n".join(",".join(map(str, r)) for r in rows)

class JsonExporter(FileExporter):
    name = "json"
    def export(self, rows):
        return json.dumps(rows)

def handle(req, user, registry):
    if user is not None:
        if user.active:
            if user.can_export:
                exp = registry[req.fmt]
                return exp.export(req.rows)
    return None
